##### 场景1：自定义安全函数。
- 错误示例：

```c
// 不符合：自定义安全函数
void Memcpy_s(void *dest, unsigned int destMax, const void *src, unsigned int count)
{
    if (destMax == 0 || destMax > SECUREC_MEM_MAX_LEN) {
        return;
    }
    if (dest == NULL || src == NULL) {
        return;
    }
    if (count > destMax) {
        return;
    }
    if (dest == src) {
        return;
    }
    if (((uint32_t)dest > (uint32_t)src && (uint32_t)dest < (uint32_t)((uint8_t *)src + count)) ||
        ((uint32_t)src > (uint32_t)dest && (uint32_t)src < (uint32_t)((uint8_t *)dest + count))) {
        return;
    }
    memcpy(dest, src, count);
    return;
}
```

