rules.bad_example:
在下面的拷贝安全函数实现中，由于不恰当的进行了类转换，因此缺乏在64位系统上的可移植性，同时，该函数的返回值也不兼容C11标准中的安全拷贝函数memcpy_s。
```C
#define SECUREC_MEM_MAX_LEN (0x7fffffffUL)
void MemcpySafe(void *dest, unsigned int destMax, const void *src, unsigned int count)
{
  if (destMax == 0 || destMax > SECUREC_MEM_MAX_LEN ) {
    return;
 }
  if (dest == NULL || src == NULL) {
    return;
 }
  if (count > destMax) {
    return;
 }
  if (dest == src) {
    return;
 }
  if (((uint32_t)dest > (uint32_t)src &&
    (uint32_t)dest < (uint32_t)(void *)((uint8_t *)src + count)) ||
   ((uint32_t)src > (uint32_t)dest &&
    (uint32_t)src < (uint32_t)(void *)((uint8_t *)dest + count))) {
    return;
 }
  memcpy(dest, src, count);
}
```

