          exit(0); // 不符合：在本例程中调用exit，导致程序产生未定义行为
      }
      return;
  }

  int main(void)
  {
      // 不符合：使用atexit()注册ProcessExit()，清理资源
      if (atexit(ProcessExit) != 0) {
          ... // 错误处理
      }
      ...
      // main函数退出
      return 0;
  }
