    } else if (a == snprintf_s) {
        /* if分支中使用了危险函数 */
        snprintf_s(deststr, 100, "%s", "ccc"); // error
        memcpy_s(deststr, 10, srcstr, 10);
    } else if (b == 1) {
        /* 分支 c == 2 使用了安全函数 */
        memcpy(deststr, srcstr, 10); // error
    } else if (c == 2) {
        /* 分支 b == 1 使用了危险函数 */
        memcpy_s(deststr, 10, srcstr, 10); // error
    } else {
        /* 分支 a == snprintf_s使用了危险函数 */
        snprintf(deststr, 100, "%s", "ych");
    }
}

// error
void test_bad6(int a, int b, char *deststr, char *srcstr)
{
    if (a > 0) {
        for (int i = 0; i < 10; i++) {
            memcpy_s(deststr, 10, srcstr, 10);
        }
    } else {
        /* 分支if 中使用了安全函数 */
        b = memcpy(deststr, srcstr, 10);
    }
}

```

