public:
    virtual ~Base() {}
    virtual void Foo();
};

class SimpleCases : public Base {
public:
    ~SimpleCases() override;            // 符合：无需再添加`virtual`
    void Foo() override;                // 符合：无需再添加`virtual`
};
```

rules.bad_example:
##### 场景1：在派生类重写虚函数时未指定`override`或`final`
- 错误示例：

```cpp
class Base {
public:
    virtual ~Base() {}
    virtual void Foo();
    virtual void Bar();
};

class SimpleCases : public Base {
public:
    virtual ~SimpleCases(); // 不符合：未指定`override`或`final`
    void Foo();             // 不符合：未指定`override`或`final`
    void Bar();             // 不符合：未指定`override`或`final`
};
```
##### 场景2：在派生类重写虚函数时增加多余的`virtual`
- 错误示例：

```cpp
class Base {
public:
    virtual ~Base() {}
    virtual void Foo();
};

class SimpleCases : public Base {
public:
    virtual ~SimpleCases() override;    // 不符合：多余的`virtual`
    virtual void Foo() override;        // 不符合：多余的`virtual`
};
```

rules.good_example:
```c
// 符合: 将函数式宏改为函数
void BubbleSort(int arr[], int n)
{
    int i, j;
    for (i = 0; i < n - 1; i++) {
        for (j = 0; j < n - i - 1; j++) {
            if (arr[j] > arr[j + 1]) {
                int temp = arr[j];
                arr[j] = arr[j + 1];
                arr[j + 1] = temp;
            }
        }
    }
}
```
